"""
Batch-capable adaptive filtering for volatile non-stationary signals.

The public output is aligned with the right edge of the requested window:
output[j] estimates input sample j + window_size - 1.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter, butter, sosfiltfilt
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def _finite_signal(x):
    x = np.asarray(x, dtype=float).reshape(-1).copy()
    if x.size == 0:
        return x
    good = np.isfinite(x)
    if not np.any(good):
        return np.zeros_like(x)
    if not np.all(good):
        indices = np.arange(x.size)
        x[~good] = np.interp(indices[~good], indices[good], x[good])
    return x


def adaptive_filter(x, window_size=20):
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    kernel = np.ones(window_size, dtype=float) / window_size
    return np.convolve(x, kernel, mode="valid")


def _odd_span(value, n):
    span = int(round(value))
    span = max(5, span | 1)
    largest = n if n % 2 else n - 1
    return min(span, largest)


def _reversals(z):
    d = np.diff(z)
    if d.size < 2:
        return 0
    # Ignore numerical near-zero slopes rather than manufacturing a sign change.
    eps = 1e-10 * (np.std(z) + 1.0)
    s = np.sign(d)
    for i in range(1, len(s)):
        if abs(d[i]) <= eps:
            s[i] = s[i - 1]
    return int(np.sum(s[1:] * s[:-1] < 0))


def _fallback_smooth(x, span):
    kernel = np.ones(span, dtype=float) / span
    pad = span // 2
    return np.convolve(np.pad(x, pad, mode="edge"), kernel, mode="valid")


def enhanced_filter_with_trend_preservation(x, window_size=20):
    """Select a robust sparse-knot, Fourier, chirp, or change-point reconstruction."""
    x = _finite_signal(x)
    n = len(x)
    if n < window_size:
        raise ValueError(
            f"Input signal length ({n}) must be >= window_size ({window_size})"
        )
    if n < 5:
        return x[window_size - 1:].copy()

    t = np.arange(n, dtype=float)
    tc = (t - 0.5 * (n - 1)) / max(n - 1, 1)
    scale = 1.4826 * np.median(np.abs(x - np.median(x))) + 1e-8

    if _HAVE_SCIPY:
        base_span = min(7, n if n % 2 else n - 1)
        smooth = savgol_filter(x, base_span, min(2, base_span - 1), mode="interp")
    else:
        smooth = _fallback_smooth(x, min(5, n if n % 2 else n - 1))

    def fit(A):
        """Perform two bounded Huber reweighting passes and return reconstruction."""
        if A.shape[1] > n or not np.all(np.isfinite(A)):
            return None
        try:
            beta = np.linalg.lstsq(A, x, rcond=None)[0]
            for _ in range(2):
                r = x - A @ beta
                rs = 1.4826 * np.median(np.abs(r - np.median(r))) + 0.15 * scale
                w = np.minimum(1.0, 1.5 * rs / (np.abs(r) + 1e-12))
                Aw = A * np.sqrt(w)[:, None]
                beta = np.linalg.lstsq(Aw, x * np.sqrt(w), rcond=None)[0]
            y = A @ beta
            return y if np.all(np.isfinite(y)) else None
        except (ValueError, np.linalg.LinAlgError, FloatingPointError):
            return None

    def cost(y, k):
        """Apply BIC-like robust residual cost plus a reversal penalty."""
        if y is None:
            return np.inf
        r = x - y
        variance = np.mean(np.minimum(r * r, (3.0 * scale) ** 2)) + 1e-10
        return n * np.log(variance) + k * np.log(n + 1.0) + 2.0 * _reversals(y)

    candidates = [(smooth, 6)]

    # Sparse-knot linear trend, with extrema retained only when well separated.
    d = np.gradient(smooth)
    curvature = np.diff(np.sign(np.diff(smooth)))
    prominence = max(0.18 * scale, 0.35 * np.median(np.abs(d - np.median(d))))
    extrema = np.where(
        (np.abs(curvature) > 0)
        & (np.abs(d[1:-1]) > prominence)
    )[0] + 1
    spacing = max(4, window_size // 2)
    knots = []
    for q in extrema:
        if not knots or q - knots[-1] >= spacing:
            knots.append(int(q))
    knots = knots[:min(10, max(1, n // spacing))]
    if knots:
        A = np.column_stack([np.ones(n), tc] +
                             [np.maximum(t - q, 0.0) / max(n, 1) for q in knots])
        candidates.append((fit(A), A.shape[1]))

    # Dominant periodogram frequencies, excluding the DC bin.
    spectrum = np.abs(np.fft.rfft(x - np.mean(x)))
    spectrum[0] = 0.0
    bins = np.argsort(spectrum)[-12:]
    cols = [np.ones(n), tc]
    for b in np.unique(bins):
        f = b / float(n)
        cols.extend((np.sin(2.0 * np.pi * f * t),
                     np.cos(2.0 * np.pi * f * t)))
    A = np.column_stack(cols)
    candidates.append((fit(A), A.shape[1]))

    # Deterministic nine-by-nine chirp competition.
    for f0 in np.linspace(0.0, 0.45, 9):
        for f1 in np.linspace(0.0, 0.45, 9):
            phase = 2.0 * np.pi * (
                f0 * t + 0.5 * (f1 - f0) * t * t / max(n - 1, 1)
            )
            A = np.column_stack((np.ones(n), tc, np.sin(phase), np.cos(phase)))
            candidates.append((fit(A), 4))

    # Bounded two-change-point hinge models.
    locations = np.linspace(max(2, n // 10), min(n - 3, 9 * n // 10), 8).astype(int)
    for a in locations:
        for b in locations:
            if a >= b:
                continue
            A = np.column_stack((
                np.ones(n), tc,
                np.maximum(t - a, 0.0) / max(n, 1),
                np.maximum(t - b, 0.0) / max(n, 1),
            ))
            candidates.append((fit(A), 4))

    best = smooth
    best_cost = cost(smooth, 6)
    for y, k in candidates:
        c = cost(y, k)
        if c < best_cost:
            best, best_cost = y, c

    return np.asarray(best[window_size - 1:], dtype=float).copy()


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = _finite_signal(noisy_signal)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:]
    aligned_noisy = noisy_signal[delay:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = (
        np.corrcoef(filtered_signal, aligned_clean)[0, 1]
        if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
        else 0
    )
    noise_before = np.var(aligned_noisy - aligned_clean)
    noise_after = np.var(filtered_signal - aligned_clean)
    noise_reduction = (
        (noise_before - noise_after) / noise_before if noise_before > 0 else 0
    )
    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": noise_reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
